pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 sentAmount) internal {
        sentAmount = bound(sentAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= sentAmount);
        uint256 prePot;
        try c.pot() returns (uint256 __r) { prePot = __r; } catch { return; }
        uint preBal = address(c).balance;
        bool reverted;
        try c.play{value: sentAmount}() { reverted = false; } catch { reverted = true; }
        assertTrue(reverted == (sentAmount != 10));
    }

    function testFuzz_run(uint256 sentAmount) public {
        _run(sentAmount);
    }

    receive() external payable {}
}
